package com.liskovsoft.smartyoutubetv2.common.exoplayer.other;

import com.liskovsoft.sharedutils.helpers.Helpers;

/**
 * Autogenerated subtitles repeat the previous lines inside every cue: VTT uses a scrolling
 * window, TTML lays out two lines. The live player path and the prefetcher must strip those
 * repeats exactly the same way, otherwise the prefetched translations are keyed differently
 * from the cues ExoPlayer hands over and the cache never hits.<br/>
 * Stateful on purpose: it compares each cue against the one before it.
 */
public class SubtitleTextDeduplicator {
    private String mBuffer;

    /**
     * @return the text to display, or {@code null} when the cue carries nothing new.
     */
    public String deduplicate(String text) {
        if (Helpers.endsWithAny(text, "\n", " ")) { // vtt subs format
            mBuffer = text;
            return null;
        }

        if (text.contains("\n")) { // ttml subs format
            String result = mBuffer != null && text.contains(mBuffer)
                    ? text.replace(mBuffer, "").replace("\n", "")
                    : text;
            String[] split = text.split("\n");
            mBuffer = split.length == 2 ? split[1] : text;
            return result;
        }

        String result = mBuffer != null ? text.replace(mBuffer, "") : text;
        mBuffer = result;
        return result;
    }
}
